class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0]*n

    def find(self, x):
        if self.parent[x]!= x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        elif self.rank[x_root] > self.rank[y_root]:
            self.parent[y_root] = x_root
        else:
            self.parent[y_root] = x_root
            self.rank[x_root] += 1

def f(N, W, P, tups):
    uf = UnionFind(N)
    for u, v, c in sorted(tups, key=lambda x:x[2]):
        if uf.find(u-1)!= uf.find(v-1):
            uf.union(u-1, v-1)
            P[uf.find(u-1)] += P[uf.find(v-1)]
            W -= c
    return max(P[(uf.find(i)) for i in range(N)])

